example:
// Enable Milky Way rendering
MilkyWay.setFlagShow(true);

// Disable Milky Way rendering
MilkyWay.setFlagShow(false);

// Toggle current state
MilkyWay.setFlagShow(!MilkyWay.getFlagShow());

if (MilkyWay.getFlagShow()) {
    core.debug("Milky Way is visible");
}

// Alternative read via Q_PROPERTY
var visible = core.getStelProperty('MilkyWay.flagMilkyWayDisplayed');
core.debug("Visible (property): " + visible);

// Make the Milky Way brighter
MilkyWay.setIntensity(1.5);

// Make the Milky Way dimmer
MilkyWay.setIntensity(0.5);

// Reset to default
MilkyWay.setIntensity(1.0);

// Read current value
var intensity = MilkyWay.getIntensity();
core.debug("Intensity: " + intensity);

// Make Milky Way colors more vivid
MilkyWay.setSaturation(1.3);

// Make Milky Way black and white
MilkyWay.setSaturation(0.0);

// Reset to natural colors
MilkyWay.setSaturation(1.0);

// Read current value
var saturation = MilkyWay.getSaturation();
core.debug("Saturation: " + saturation);

// Method 1: core.vec3f literal (both Qt5 and Qt6)
MilkyWay.setColor(core.vec3f(1.0, 1.0, 1.0));   // natural white
MilkyWay.setColor(core.vec3f(1.0, 0.95, 0.9));  // subtle warm tint
MilkyWay.setColor(core.vec3f(0.85, 0.9, 1.0));  // bluish tint

// Method 2: Color wrapper (recommended when computing/modifying)
var c = new Color(0.7, 1.0, 0.8);
MilkyWay.setColor(c.toVec3f());

// Read back safely
var current = new Color(MilkyWay.getColor());
core.debug("Milky Way color: " + current.toRGBString());

var color = new Color(MilkyWay.getColor());
core.debug("Milky Way color: " + color.toRGBString());
core.debug("Hex: " + color.toHex());

var r = color.getR();
var g = color.getG();
var b = color.getB();
core.debug("R=" + r + " G=" + g + " B=" + b);

// Alternative via Q_PROPERTY (wrap in Color!)
var propColor = new Color(core.getStelProperty('MilkyWay.color'));
core.debug("Color via property: " + propColor.toRGBString());
